def generate_events(output_path):
    from pathlib import Path
    output_path = Path(output_path)
    all_events = CPI_RELEASES + PPI_RELEASES + FOMC_RELEASES + LABOR_RELEASES + JOLTS_RELEASES + GDP_RELEASES + ISM_RELEASES + RETAIL_SALES_RELEASES + CONSUMER_CONFIDENCE_RELEASES + PCE_RELEASES
    all_events.sort(key=lambda x: x[2])
    seen = set()
    deduped = []
    for e in all_events:
        key = (e[0], e[2])
        if key not in seen:
            seen.add(key)
            deduped.append(e)
    all_events = deduped
    rows = [{'event_id': i + 1, 'timestamp': ts, 'event_name': name, 'event_category': cat, 'event_flag': 1} for i, (name, cat, ts) in enumerate(all_events)]
    output_path.parent.mkdir(parents=True, exist_ok=True)
    import csv
    with open(output_path, 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['event_id', 'timestamp', 'event_name', 'event_category', 'event_flag'])
        writer.writeheader()
        writer.writerows(rows)
    print(f'\nWrote {len(rows)} events to: {output_path}\n')
    counts = {}
    for name, cat, _ in all_events:
        counts[name] = counts.get(name, 0) + 1
    for name, count in sorted(counts.items(), key=lambda x: -x[1]):
        print(f'  {name:<28} {count:>4} events')
    cat_counts = {}
    for _, cat, _ in all_events:
        cat_counts[cat] = cat_counts.get(cat, 0) + 1
    print(f'\n  TOTAL: {len(rows)}')
    print(f"  Date range: {rows[0]['timestamp'][:10]}  ->  {rows[-1]['timestamp'][:10]}")
    print('\n  By category:')
    for cat, count in sorted(cat_counts.items(), key=lambda x: -x[1]):
        print(f'    {cat:<20} {count:>4}')
if __name__ == '__main__':
    from pathlib import Path
    THIS_DIR = Path(__file__).resolve().parent
    OUTPUT_PATH = THIS_DIR.parent / 'data' / 'events.csv'
    generate_events(OUTPUT_PATH)
